export const MAPPINGS = ROWS.map(([rule, category, use_case, tactics, techniques, sensor_kinds, sensor, indicator, analytic, d3fend_detect, d3fend_respond, response, test]) => ({ rule, category, use_case: use_case[0], use_case_ar: use_case[1], tactics, techniques, sensor_kinds, sensor, indicator, analytic, d3fend_detect, d3fend_respond, response, test }));

export function mappingFor(ruleId) {
  return MAPPINGS.find(m => m.rule === ruleId) || MAPPINGS.find(m => m.rule.endsWith('*') && ruleId?.startsWith(m.rule.slice(0, -1))) || null;
}
// ATT&CK Navigator layer (format 4.5) for the enterprise domain; score = alerts raised, comment = rules.
export function navigatorLayer(rows, name = 'CyberGuard detection coverage') {
  const by = new Map();
  for (const r of rows) for (const t of r.techniques.filter(t => !/^T0\d{3}$/.test(t) && t !== 'T1404' && !t.startsWith('AML.'))) { const x = by.get(t) || { techniqueID: t, score: 0, rules: new Set() }; x.score += r.alerts_total || 0; x.rules.add(r.rule); by.set(t, x); }
  return { name, versions: { attack: '16', navigator: '5.1.0', layer: '4.5' }, domain: 'enterprise-attack', description: 'Techniques covered by CyberGuard rules; score is the number of alerts raised.', gradient: { colors: ['#e8f1fb', '#1f6feb'], minValue: 0, maxValue: Math.max(1, ...[...by.values()].map(x => x.score)) },
    techniques: [...by.values()].map(x => ({ techniqueID: x.techniqueID, score: x.score, enabled: true, comment: [...x.rules].join(', ') })).sort((a, b) => a.techniqueID.localeCompare(b.techniqueID)) };
}
